{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목을 실행 계획과 조회 구조에 근거해 파악하고, 원인에 적합한 개선을 적용한 뒤 전후 성능을 수치로 검증하는 능력을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회가 느렸던 상황과 해당 쿼리의 조회 조건 및 데이터 접근 구조를 설명한다.",
          "task": "본인이 맡은 병목 분석과 쿼리 개선의 범위 및 확인하려던 성능 문제를 설명한다.",
          "action": "실행 계획에서 확인한 병목 근거를 제시하고, 조회 조건에 맞는 인덱스와 조인 변경을 선택한 이유 및 적용 과정을 설명한다.",
          "result": "개선 전후 응답 시간을 측정 조건과 함께 비교하고, 적용한 변경이 병목 해소에 미친 영향을 설명한다."
        },
        "expectedEvidence": [
          "실행 계획의 스캔 방식, 조회 행 수, 조인 방식 등 실제로 확인한 정보와 병목 판단의 연결",
          "조회 조건 및 테이블 접근 구조와 인덱스·조인 변경 선택 사이의 인과관계",
          "본인이 수행한 분석 및 수정 작업의 구체적인 내용",
          "비교 가능한 측정 조건에서 확인한 개선 전후 응답 시간과 개선 효과"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄였던 경험을 바탕으로, 병목을 판단한 근거부터 개선 효과를 검증하기까지의 과정을 설명해 주세요.",
      "answerTip": "기억나는 사례를 차분하게 풀어 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 구체적인 정보와 조회 구조를 연결해 병목 원인을 설명한다.",
            "본인이 적용한 인덱스와 조인 변경이 원인에 적합한 이유 및 수정 과정을 구체적으로 설명한다.",
            "개선 전후 수치를 비교 가능한 측정 조건과 함께 제시하고 변경에 따른 성능 효과를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "병목 근거와 인덱스 또는 조인 변경의 연관성은 설명하지만 실행 계획 해석이나 본인의 수정 과정이 일부 불명확하다.",
            "개선 전후 수치는 제시하지만 측정 조건이나 변경 효과를 확인한 과정이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "실행 계획이나 조회 구조에 근거한 원인 설명 없이 인덱스를 추가했다는 사실만 나열한다.",
            "개선 방법이 병목 원인과 어떻게 연결되는지 설명하지 못한다.",
            "개선 전후 측정 수치를 제시하지 못하거나 기록된 수치를 반복할 뿐 검증 과정을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 발생한 서버 오류를 로그와 모니터링 근거로 추적해 원인을 좁히고, 즉시 복구와 재발 방지를 구분하여 실행하고 확인하는 능력을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 배포 다음 날 알림 중복 발송 문의가 들어온 상황과 확인된 오류 현상을 설명한다.",
          "task": "중복 발송의 원인을 추적하고 서비스를 정상화하며 동일한 장애의 반복을 막기 위해 본인이 맡은 역할을 설명한다.",
          "action": "시간순 로그와 서버별 실행 기록, 확인 가능한 모니터링 정보를 대조해 스케줄러 중복 실행으로 원인을 좁힌 과정을 설명하고, 당장 중복 발송을 멈추기 위한 조치와 잠금 및 배포 체크리스트 등 재발 방지 조치를 구분한다.",
          "result": "조치 후 로그나 발송 건수 등으로 정상화를 확인한 근거와 재발 방지 조치의 적용 및 확인 결과를 설명한다."
        },
        "expectedEvidence": [
          "오류 시점의 로그와 서버별 실행 기록, 관련 지표 등 확인 가능한 근거를 통한 추적 과정",
          "초기 가설을 검토하고 두 서버의 스케줄러 중복 실행으로 원인을 좁힌 판단 근거",
          "당장의 서비스 정상화 조치와 동일 원인의 재발 방지 조치를 구분한 설명",
          "중복 실행을 막는 잠금 조치가 원인에 대응하는 방식과 배포 체크리스트 반영 내용",
          "조치 이후 중복 발송 해소 및 재발 방지 효과를 확인한 로그나 지표 등 구체적 근거"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림이 중복 발송됐던 경험을 바탕으로, 로그로 원인을 좁힌 뒤 복구와 재발 방지를 진행한 과정을 설명해 주세요.",
      "answerTip": "당시 경험을 순서대로 이야기해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "시간순 로그와 서버별 실행 기록 또는 관련 지표를 연결해 초기 가설을 검토하고 스케줄러 중복 실행을 원인으로 판단한 과정을 구체적으로 설명한다.",
            "당장의 정상화 조치와 재발 방지 조치를 목적에 따라 구분하고, 잠금 방식과 체크리스트 변경이 동일 장애를 막는 이유를 설명한다.",
            "본인이 수행한 조치와 조치 후 정상화 및 재발 방지 효과를 확인한 구체적인 근거를 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "로그에서 중복 실행을 확인한 근거와 원인에 대응하는 수정 내용은 설명하지만 가설 검토나 서버별 기록 비교 과정이 부족하다.",
            "복구와 재발 방지 조치를 제시하지만 두 조치의 구분 또는 적용 방식이 일부 불명확하다.",
            "정상화 결과는 설명하지만 조치 이후의 로그·지표 확인이나 재발 방지 효과의 검증 근거가 제한적이다."
          ]
        },
        "poor": {
          "criteria": [
            "로그나 지표에 근거한 추적 과정 없이 스케줄러가 원인이었다는 결론만 제시한다.",
            "원인과 연결된 복구 조치나 재발 방지 방안을 구체적으로 설명하지 못한다.",
            "조치 후 중복 발송이 해소되었는지 확인한 근거를 제시하지 못한다."
          ]
        }
      }
    }
  ]
}
